     1|/**
     2| * IVX Owner Conversation State — durable pending-action memory for owner-ai chat.
     3| *
     4| * Purpose: fix the conversation state-loss bug where the owner asks a question
     5| * ("How many properties do we have?"), the AI asks for permission, the owner
     6| * approves, and then the AI loses the original request and produces a generic
     7| * deployment plan.
     8| *
     9| * This service stores a structured pending-action record per conversation and
    10| * per owner. It is read/written on every owner-ai turn so follow-ups resolve
    11| * the original intent instead of being reinterpreted.
    12| *
    13| * Persistence: uses the same durable-store abstraction as ivx-ia-memory-store
    14| * (Supabase-backed when configured, otherwise local JSON). Survives Render
    15| * restarts and app reloads.
    16| *
    17| * Security: NEVER stores secrets, raw SQL, or credentials. Only stores the
    18| * owner-visible intent, target table/resource, and last-known status.
    19| */
    20|import { mkdir, readFile, writeFile } from 'node:fs/promises';
    21|import path from 'node:path';
    22|import { auditDir } from './ivx-data-root';
    23|import {
    24|  isDurableStoreConfigured,
    25|  readDurableJson,
    26|  writeDurableJson,
    27|  appendDurableEvent,
    28|} from './ivx-durable-store';
    29|import { detectCountIntent, runDbCounts, buildCountGroundingBlock, type CountTarget } from './ivx-db-count';
    30|import { createRequestId } from './ivx-request-id';
    31|
    32|export const IVX_OWNER_CONVERSATION_STATE_MARKER = 'ivx-owner-conversation-state-v1-2026-07-30';
    33|
    34|const ROOT = auditDir('owner-conversation-state');
    35|const STATE = path.join(ROOT, 'states.json');
    36|
    37|type ExecutionState = 'PENDING_APPROVAL' | 'EXECUTING' | 'COMPLETED' | 'FAILED' | 'BLOCKED' | 'CANCELLED';
    38|
    39|export type OwnerActionType =
    40|  | 'database_read'
    41|  | 'database_read_active'
    42|  | 'database_list_latest'
    43|  | 'database_write'
    44|  | 'code_change'
    45|  | 'deployment'
    46|  | 'explanation'
    47|  | 'information'
    48|  | 'task_status'
    49|  | 'task_cancel'
    50|  | 'unknown';
    51|
    52|export type PendingOwnerAction = {
    53|  actionId: string;
    54|  conversationId: string;
    55|  ownerId: string;
    56|  createdAt: string;
    57|  updatedAt: string;
    58|  executionState: ExecutionState;
    59|  originalQuestion: string;
    60|  actionType: OwnerActionType;
    61|  resource: string | null;
    62|  operation: string | null;
    63|  authorizationRequired: boolean;
    64|  authorizationStatus: 'pending' | 'granted' | 'denied' | 'not_required';
    65|  languagePreference: string | null;
    66|  lastResultSummary: string | null;
    67|  lastError: string | null;
    68|  traceId: string | null;
    69|  // Generic metadata (e.g. requested limit for list queries, filter for active queries).
    70|  metadata: Record<string, unknown>;
    71|};
    72|
    73|export type OwnerConversationState = {
    74|  conversationId: string;
    75|  ownerId: string;
    76|  updatedAt: string;
    77|  languagePreference: string | null;
    78|  activeActionId: string | null;
    79|  actions: PendingOwnerAction[];
    80|  lastCompletedActionId: string | null;
    81|  unresolvedQuestion: string | null;
    82|  lastVerifiedProductionState: Record<string, unknown> | null;
    83|  readOnlyAuthorized: boolean;
    84|};
    85|
    86|function nowIso(): string {
    87|  return new Date().toISOString();
    88|}
    89|
    90|function asTrimmedString(value: unknown): string {
    91|  return typeof value === 'string' ? value.trim() : '';
    92|}
    93|
    94|async function readStates(): Promise<OwnerConversationState[]> {
    95|  if (isDurableStoreConfigured()) {
    96|    return readDurableJson<OwnerConversationState[]>(STATE, []);
    97|  }
    98|  try {
    99|    const raw = await readFile(STATE, 'utf8');
   100|    return JSON.parse(raw) as OwnerConversationState[];
   101|  } catch {
   102|    return [];
   103|  }
   104|}
   105|
   106|async function writeStates(value: OwnerConversationState[]): Promise<void> {
   107|  if (isDurableStoreConfigured()) {
   108|    await writeDurableJson(STATE, value);
   109|    return;
   110|  }
   111|  await mkdir(ROOT, { recursive: true });
   112|  await writeFile(STATE, JSON.stringify(value, null, 2), 'utf8');
   113|}
   114|
   115|async function appendStateEvent(event: Record<string, unknown>): Promise<void> {
   116|  const eventFile = path.join(ROOT, 'events.jsonl');
   117|  if (isDurableStoreConfigured()) {
   118|    try {
   119|      await appendDurableEvent(eventFile, event);
   120|    } catch {
   121|      // Forensic log is best-effort.
   122|    }
   123|    return;
   124|  }
   125|  try {
   126|    await mkdir(ROOT, { recursive: true });
   127|    await writeFile(eventFile, `${JSON.stringify(event)}\n`, { flag: 'a' });
   128|  } catch {
   129|    // Best-effort.
   130|  }
   131|}
   132|
   133|function defaultState(conversationId: string, ownerId: string): OwnerConversationState {
   134|  return {
   135|    conversationId,
   136|    ownerId,
   137|    updatedAt: nowIso(),
   138|    languagePreference: null,
   139|    activeActionId: null,
   140|    actions: [],
   141|    lastCompletedActionId: null,
   142|    unresolvedQuestion: null,
   143|    lastVerifiedProductionState: null,
   144|    readOnlyAuthorized: false,
   145|  };
   146|}
   147|
   148|export async function getOwnerConversationState(
   149|  conversationId: string,
   150|  ownerId: string,
   151|): Promise<OwnerConversationState> {
   152|  const states = await readStates();
   153|  const existing = states.find((s) => s.conversationId === conversationId && s.ownerId === ownerId);
   154|  if (existing) return existing;
   155|  return defaultState(conversationId, ownerId);
   156|}
   157|
   158|export async function setOwnerConversationState(
   159|  state: OwnerConversationState,
   160|): Promise<OwnerConversationState> {
   161|  const states = await readStates();
   162|  const index = states.findIndex(
   163|    (s) => s.conversationId === state.conversationId && s.ownerId === state.ownerId,
   164|  );
   165|  const next = { ...state, updatedAt: nowIso() };
   166|  if (index >= 0) {
   167|    states[index] = next;
   168|  } else {
   169|    states.push(next);
   170|  }
   171|  await writeStates(states);
   172|  await appendStateEvent({ type: 'upsert', conversationId: state.conversationId, ownerId: state.ownerId, at: next.updatedAt });
   173|  return next;
   174|}
   175|
   176|export async function clearActiveAction(
   177|  conversationId: string,
   178|  ownerId: string,
   179|): Promise<OwnerConversationState> {
   180|  const state = await getOwnerConversationState(conversationId, ownerId);
   181|  const next = { ...state, activeActionId: null, updatedAt: nowIso() };
   182|  return setOwnerConversationState(next);
   183|}
   184|
   185|export async function addPendingAction(
   186|  conversationId: string,
   187|  ownerId: string,
   188|  input: {
   189|    originalQuestion: string;
   190|    actionType: OwnerActionType;
   191|    resource: string | null;
   192|    operation: string | null;
   193|    authorizationRequired: boolean;
   194|    languagePreference?: string | null;
   195|    metadata?: Record<string, unknown>;
   196|  },
   197|): Promise<PendingOwnerAction> {
   198|  const state = await getOwnerConversationState(conversationId, ownerId);
   199|  const action: PendingOwnerAction = {
   200|    actionId: `act-${createRequestId()}`,
   201|    conversationId,
   202|    ownerId,
   203|    createdAt: nowIso(),
   204|    updatedAt: nowIso(),
   205|    executionState: 'PENDING_APPROVAL',
   206|    originalQuestion: input.originalQuestion,
   207|    actionType: input.actionType,
   208|    resource: input.resource,
   209|    operation: input.operation,
   210|    authorizationRequired: input.authorizationRequired,
   211|    authorizationStatus: input.authorizationRequired ? 'pending' : 'not_required',
   212|    languagePreference: input.languagePreference ?? state.languagePreference,
   213|    lastResultSummary: null,
   214|    lastError: null,
   215|    traceId: null,
   216|    metadata: input.metadata ?? {},
   217|  };
   218|  const actions = [...state.actions, action];
   219|  // Keep only the most recent 20 actions per conversation to bound size.
   220|  const trimmed = actions.slice(-20);
   221|  await setOwnerConversationState({
   222|    ...state,
   223|    actions: trimmed,
   224|    activeActionId: action.actionId,
   225|    unresolvedQuestion: input.originalQuestion,
   226|  });
   227|  await appendStateEvent({
   228|    type: 'pending_action_added',
   229|    conversationId,
   230|    ownerId,
   231|    actionId: action.actionId,
   232|    actionType: action.actionType,
   233|    resource: action.resource,
   234|    at: action.createdAt,
   235|  });
   236|  return action;
   237|}
   238|
   239|export async function updateAction(
   240|  conversationId: string,
   241|  ownerId: string,
   242|  actionId: string,
   243|  patch: Partial<PendingOwnerAction>,
   244|): Promise<PendingOwnerAction | null> {
   245|  const state = await getOwnerConversationState(conversationId, ownerId);
   246|  const actionIndex = state.actions.findIndex((a) => a.actionId === actionId);
   247|  if (actionIndex < 0) return null;
   248|  const actions = [...state.actions];
   249|  const updated: PendingOwnerAction = { ...actions[actionIndex]!, ...patch, updatedAt: nowIso() };
   250|  actions[actionIndex] = updated;
   251|  await setOwnerConversationState({ ...state, actions });
   252|  return updated;
   253|}
   254|
   255|export async function getActiveAction(
   256|  conversationId: string,
   257|  ownerId: string,
   258|): Promise<PendingOwnerAction | null> {
   259|  const state = await getOwnerConversationState(conversationId, ownerId);
   260|  if (!state.activeActionId) return null;
   261|  return state.actions.find((a) => a.actionId === state.activeActionId) ?? null;
   262|}
   263|
   264|export async function resolveActiveAction(
   265|  conversationId: string,
   266|  ownerId: string,
   267|  status: 'granted' | 'denied',
   268|): Promise<PendingOwnerAction | null> {
   269|  const state = await getOwnerConversationState(conversationId, ownerId);
   270|  if (!state.activeActionId) return null;
   271|  const actionIndex = state.actions.findIndex((a) => a.actionId === state.activeActionId);
   272|  if (actionIndex < 0) return null;
   273|  const actions = [...state.actions];
   274|  const updated: PendingOwnerAction = {
   275|    ...actions[actionIndex]!,
   276|    authorizationStatus: status,
   277|    executionState: status === 'granted' ? 'EXECUTING' : 'CANCELLED',
   278|    updatedAt: nowIso(),
   279|  };
   280|  actions[actionIndex] = updated;
   281|  await setOwnerConversationState({ ...state, actions });
   282|  return updated;
   283|}
   284|
   285|const APPROVAL_PHRASES = [
   286|  'proceed', 'procede', 'hazlo', 'hazlo ahora', 'autorizado', 'te autorizo',
   287|  'la quiero', 'lo quiero', 'la quiero ahora', 'lo quiero ahora',
   288|  'sí', 'si', 'yes', 'go ahead', 'do it now', 'do it', 'ejecutalo', 'ejecútalo',
   289|  'continua', 'continúa', 'aprobado', 'i approve', 'you have permission',
   290|  'adelante', 'vamos', 'confirma', 'confirmado', 'dale', 'ok', 'okay',
   291|  'está bien', 'esta bien', 'por supuesto', 'claro', 'hazlo por favor',
   292|  'procede por favor', 'execute', 'run it', 'check now',
   293|];
   294|
   295|const DENIAL_PHRASES = [
   296|  'cancel', 'cancela', 'cancelar', 'stop', 'detente', 'no lo hagas',
   297|  'no procedas', 'no procede', 'denied', 'denegado', 'rechazado', 'rechaza',
   298|  'olvídalo', 'olvidalo', 'nvm', 'never mind', 'forget it',
   299|];
   300|
   301|export function detectOwnerApproval(message: string): 'approve' | 'deny' | 'neutral' {
   302|  const normalized = asTrimmedString(message).toLowerCase().replace(/[^a-z0-9áéíóúñü\s]/g, ' ').replace(/\s+/g, ' ').trim();
   303|  if (!normalized) return 'neutral';
   304|  const tokens = normalized.split(' ');
   305|
   306|  function matchesPhrase(phrase: string): boolean {
   307|    const p = phrase.toLowerCase();
   308|    if (p.includes(' ')) {
   309|      // Multi-word: bounded by spaces or string edges
   310|      return normalized === p || normalized.startsWith(p + ' ') || normalized.endsWith(' ' + p) || normalized.includes(' ' + p + ' ');
   311|    }
   312|    // Single-word: exact token match (prevents 'si' matching 'sistema', 'no' matching 'normal')
   313|    return tokens.includes(p);
   314|  }
   315|
   316|  // Check denial first so "no, proceed" is not treated as approval.
   317|  for (const phrase of DENIAL_PHRASES) {
   318|    if (matchesPhrase(phrase)) return 'deny';
   319|  }
   320|  for (const phrase of APPROVAL_PHRASES) {
   321|    if (matchesPhrase(phrase)) return 'approve';
   322|  }
   323|  return 'neutral';
   324|}
   325|
   326|export function isApprovalQuestion(message: string): boolean {
   327|  const normalized = asTrimmedString(message).toLowerCase();
   328|  return /\b(puedes?|puedo|can you|podrías?|podrias?|would you|could you)\b.{0,40}\b(revisar|consultar|ver|check|inspect|query|look at|look up|buscar|contar|count)\b/i.test(normalized)
   329|    || /\b(te parece|está bien|esta bien|ok\?|okay\?|yes\?|sí\?)\b/i.test(normalized);
   330|}
   331|
   332|export function isInformationRequest(message: string): boolean {
   333|  const normalized = asTrimmedString(message).toLowerCase();
   334|  return /\b(how many|cuántas?|cuantas?|cuántos?|cuantos?|number of|how much|what is|what's|cuál es|cual es|how many|are there|hay|tell me|dime|show me|muéstrame|muestrame|list|latest|últimas?|ultimas?|últimos?|ultimos?|recent|recientes|status of|estado de)\b/i.test(normalized);
   335|}
   336|
   337|export function classifyOwnerActionType(message: string): { actionType: OwnerActionType; resource: string | null; operation: string | null; metadata: Record<string, unknown> } {
   338|  const normalized = asTrimmedString(message).toLowerCase();
   339|  const countTargets = detectCountIntent(message);
   340|
   341|  // Property / real-estate questions.
   342|  const isPropertyQuestion = /\b(propiedad|propiedades|property|properties|casa|casas|deal|deals|project|projects|jv\s*deal|inmueble|inmuebles)\b/i.test(normalized);
   343|  const wantsActive = /\b(activas?|activos?|active|activo|en\s*venta|for\s+sale|available|disponible|disponibles|live|published)\b/i.test(normalized);
   344|  const wantsLatest = /\b(últimas?|ultimas?|últimos?|ultimos?|latest|recent|recientes|last\s+five|last\s+5|últimas\s+cinco|ultimas\s+cinco|muéstrame|muestrame|show\s+me|list)\b/i.test(normalized);
   345|  const listLimitMatch = normalized.match(/\b(\d+)\b/);
   346|  const listLimit = listLimitMatch ? Math.min(Math.max(Number(listLimitMatch[1]), 1), 100) : 5;
   347|
   348|  if (isPropertyQuestion) {
   349|    if (wantsLatest) {
   350|      return { actionType: 'database_list_latest', resource: 'properties', operation: 'select_latest', metadata: { limit: listLimit } };
   351|    }
   352|    if (wantsActive) {
   353|      return { actionType: 'database_read_active', resource: 'properties', operation: 'count_active', metadata: {} };
   354|    }
   355|    return { actionType: 'database_read', resource: 'properties', operation: 'count', metadata: {} };
   356|  }
   357|
   358|  // Generic count intents mapped to other targets.
   359|  if (countTargets.length > 0) {
   360|    return { actionType: 'database_read', resource: countTargets[0]!, operation: 'count', metadata: { countTargets } };
   361|  }
   362|
   363|  // Task control / status / cancel.
   364|  if (/(estado|status|where are we|where were we|dónde nos quedamos|donde nos quedamos|qué estabas haciendo|que estabas haciendo|what were you doing|dónde quedamos|donde quedamos)/i.test(normalized)) {
   365|    return { actionType: 'task_status', resource: null, operation: 'status', metadata: {} };
   366|  }
   367|  if (/\b(cancel|cancela|cancelar|stop|detente)\b/i.test(normalized)) {
   368|    return { actionType: 'task_cancel', resource: null, operation: 'cancel', metadata: {} };
   369|  }
   370|  if (/\b(continue|continuar|continúa|continua|resume|reanudar|go on)\b/i.test(normalized)) {
   371|    return { actionType: 'task_status', resource: null, operation: 'resume', metadata: {} };
   372|  }
   373|
   374|  // Code change / deployment.
   375|  if (/\b(fix|arregla|repara|soluciona|corrige|add|agrega|añade|create|crea|deploy|despliega|deployar|update|actualiza|change|cambia|modify|modifica)\b/i.test(normalized)) {
   376|    if (/\b(deploy|despliega|deployar|deployar|production|producción|produccion|live)\b/i.test(normalized)) {
   377|      return { actionType: 'deployment', resource: null, operation: 'deploy', metadata: {} };
   378|    }
   379|    return { actionType: 'code_change', resource: null, operation: 'fix', metadata: {} };
   380|  }
   381|
   382|  if (isInformationRequest(message)) {
   383|    return { actionType: 'information', resource: null, operation: 'answer', metadata: {} };
   384|  }
   385|
   386|  if (/\b(explica|explicar|explain|why|por qué|porque|porqué|how does|how do|cómo|como|architecture|arquitectura)\b/i.test(normalized)) {
   387|    return { actionType: 'explanation', resource: null, operation: 'explain', metadata: {} };
   388|  }
   389|
   390|  return { actionType: 'unknown', resource: null, operation: null, metadata: {} };
   391|}
   392|
   393|
   394|export function classifyOwnerActionTypeWithContext(
   395|  message: string,
   396|  previousAction: PendingOwnerAction | null,
   397|): { actionType: OwnerActionType; resource: string | null; operation: string | null; metadata: Record<string, unknown> } {
   398|  const classified = classifyOwnerActionType(message);
   399|  if (classified.resource === 'properties' || classified.resource === 'deals' || classified.actionType === 'database_read' || classified.actionType === 'database_read_active' || classified.actionType === 'database_list_latest') {
   400|    return classified;
   401|  }
   402|  if ((classified.actionType === 'information' || classified.actionType === 'unknown') && previousAction && (previousAction.resource === 'properties' || previousAction.resource === 'deals')) {
   403|    const normalized = asTrimmedString(message).toLowerCase();
   404|    const wantsActive = /\b(activas?|activos?|active|activo|en\s*venta|for\s+sale|available|disponible|disponibles|live|published)\b/i.test(normalized);
   405|    const wantsLatest = /\b(últimas?|ultimas?|últimos?|ultimos?|latest|recent|recientes|last\s+five|last\s+5|últimas\s+cinco|ultimas\s+cinco|muéstrame|muestrame|show\s+me|list)\b/i.test(normalized);
   406|    const listLimitMatch = normalized.match(/\b(\d+)\b/);
   407|    const listLimit = listLimitMatch ? Math.min(Math.max(Number(listLimitMatch[1]), 1), 100) : 5;
   408|    if (wantsActive) return { actionType: 'database_read_active', resource: 'properties', operation: 'count_active', metadata: {} };
   409|    if (wantsLatest) return { actionType: 'database_list_latest', resource: 'properties', operation: 'select_latest', metadata: { limit: listLimit } };
   410|    return { actionType: 'database_read', resource: 'properties', operation: 'count', metadata: {} };
   411|  }
   412|  return classified;
   413|}
   414|
   415|export function isReadOnlyActionType(actionType: OwnerActionType): boolean {
   416|  return actionType === 'database_read' || actionType === 'database_read_active' || actionType === 'database_list_latest' || actionType === 'explanation' || actionType === 'task_status';
   417|}
   418|
   419|export async function executeReadOnlyAction(
   420|  action: PendingOwnerAction,
   421|): Promise<{ answer: string; evidence: Record<string, unknown>; ok: boolean; error: string | null }> {
   422|  const { actionType, resource, originalQuestion, metadata } = action;
   423|  const ts = nowIso();
   424|  const lang = action.languagePreference ?? 'en';
   425|  const isSpanish = /es/i.test(lang) || /\b(cuántas|cuantas|propiedades|activas|muestrame|muéstrame|dónde|donde|qué|que)\b/i.test(originalQuestion);
   426|
   427|  try {
   428|    if (actionType === 'database_read' && resource === 'properties') {
   429|      const countTargets = (metadata.countTargets as CountTarget[] | undefined) ?? ['jv_deals'];
   430|      const report = await runDbCounts(countTargets);
   431|      const result = report.results[0] ?? {
   432|        ok: false, count: null, table: null, reason: 'not_configured', detail: 'No result', queriedAt: ts, executed: false, target: 'jv_deals', httpStatus: null,
   433|      };
   434|      if (result.ok && result.count !== null) {
   435|        const answer = isSpanish
   436|          ? `Actualmente tenemos ${result.count} propiedades en la base de datos de producción.\n\nSource: Supabase\nTable: ${result.table ?? 'unknown'}\nQuery type: read-only count\nTimestamp: ${result.queriedAt}\nStatus: verified`
   437|          : `We currently have ${result.count} properties in the production database.\n\nSource: Supabase\nTable: ${result.table ?? 'unknown'}\nQuery type: read-only count\nTimestamp: ${result.queriedAt}\nStatus: verified`;
   438|        return { answer, evidence: { result, report }, ok: true, error: null };
   439|      }
   440|      const answer = isSpanish
   441|        ? `No pude obtener el conteo de propiedades.\n\nError: ${result.detail}\nTrace ID: ${action.actionId}\nRequired action: ${result.reason === 'not_configured' ? 'Configure Supabase service role key' : 'Verify the table exists in Supabase'}`
   442|        : `I could not retrieve the property count.\n\nError: ${result.detail}\nTrace ID: ${action.actionId}\nRequired action: ${result.reason === 'not_configured' ? 'Configure Supabase service role key' : 'Verify the table exists in Supabase'}`;
   443|      return { answer, evidence: { result, report }, ok: false, error: result.detail };
   444|    }
   445|
   446|    if (actionType === 'database_read_active' && resource === 'properties') {
   447|      // Try to count active properties by guessing the status column.
   448|      const { countActiveProperties } = await import('./ivx-property-queries');
   449|      const result = await countActiveProperties();
   450|      if (result.ok && result.count !== null) {
   451|        const answer = isSpanish
   452|          ? `Actualmente tenemos ${result.count} propiedades activas en la base de datos de producción.\n\nSource: Supabase\nTable: ${result.table ?? 'unknown'}\nFilter: ${result.filter ?? 'active'}\nQuery type: read-only filtered count\nTimestamp: ${result.queriedAt}\nStatus: verified`
   453|          : `We currently have ${result.count} active properties in the production database.\n\nSource: Supabase\nTable: ${result.table ?? 'unknown'}\nFilter: ${result.filter ?? 'active'}\nQuery type: read-only filtered count\nTimestamp: ${result.queriedAt}\nStatus: verified`;
   454|        return { answer, evidence: { result }, ok: true, error: null };
